<?php namespace App\Services; use App\Models\{Job,JobService as JobServiceModel,Service,Invoice,InvoiceItem,Inventory,InventoryMovement}; use Illuminate\Support\Facades\DB;
class JobService { public function create(array $data): Job {return DB::transaction(function()use($data){$job=Job::create($data+['job_number'=>$this->number(),'status'=>'checked_in','checked_in_at'=>now()]); foreach($data['service_ids']??[] as $sid){$s=Service::findOrFail($sid); JobServiceModel::create(['job_id'=>$job->id,'service_id'=>$s->id,'name_snapshot'=>$s->name,'unit_price'=>$s->base_price,'approval_status'=>'approved']);} return $job;});} public function status(Job $job,string $status):void{$allowed=['waiting_for_checkin'=>'checked_in','checked_in'=>'inspection_pending','inspection_pending'=>'inspection_completed','inspection_completed'=>'customer_approval_pending','customer_approval_pending'=>'approved','approved'=>'waiting_for_parts','waiting_for_parts'=>'in_service','in_service'=>'quality_check','quality_check'=>'completed','completed'=>'ready_for_payment','ready_for_payment'=>'paid','paid'=>'delivered']; if(($allowed[$job->status]??null)!==$status && !in_array($status,['on_hold','cancelled','awaiting_customer','parts_unavailable','rework_required'],true)) abort(422,'Invalid status transition.'); $job->update(['status'=>$status,'completed_at'=>$status==='completed'?now():$job->completed_at]);} public function invoice(Job $job):Invoice{ return DB::transaction(function()use($job){$items=$job->services()->where('removed',false)->get();$parts=$job->parts()->where('approved',true)->get();$subtotal=$items->sum(fn($i)=>$i->unit_price*$i->quantity)+$parts->sum(fn($p)=>$p->unit_price*$p->quantity);$tax=0;$invoice=Invoice::create(['business_id'=>$job->business_id,'branch_id'=>$job->branch_id,'customer_id'=>$job->customer_id,'job_id'=>$job->id,'invoice_number'=>'INV-'.now()->format('Y').'-'.str_pad((string)(Invoice::max('id')+1),6,'0',STR_PAD_LEFT),'subtotal'=>$subtotal,'tax'=>$tax,'total'=>$subtotal,'balance'=>$subtotal]);foreach($items as $i)InvoiceItem::create(['invoice_id'=>$invoice->id,'item_type'=>'service','item_id'=>$i->service_id,'description'=>$i->name_snapshot,'quantity'=>$i->quantity,'unit_price'=>$i->unit_price,'line_total'=>$i->unit_price*$i->quantity]);foreach($parts as $p)InvoiceItem::create(['invoice_id'=>$invoice->id,'item_type'=>'part','item_id'=>$p->product_id,'description'=>'Part #'.$p->product_id,'quantity'=>$p->quantity,'unit_price'=>$p->unit_price,'line_total'=>$p->unit_price*$p->quantity]);return $invoice;}); } private function number(){return 'JOB-'.now()->format('Y').'-'.str_pad((string)(Job::max('id')+1),6,'0',STR_PAD_LEFT);}}
